export const LOGIC_SOURCES=['cpu','memory','battery','network','musicPlaying','charging','spectrumBass','spectrumMid','spectrumTreble','spectrumBeat'];
export const LOGIC_OPERATORS=['lt','lte','eq','gte','gt','neq'];
export function sourceValue(source,data={}){return ({cpu:data.cpu,memory:data.memory,battery:data.battery,network:data.network,musicPlaying:data.musicPlaying,charging:data.charging,spectrumBass:data.spectrumBass,spectrumMid:data.spectrumMid,spectrumTreble:data.spectrumTreble,spectrumBeat:data.spectrumBeat})[source];}
export function matches(rule,data){if(!rule?.enabled)return false;const actual=sourceValue(rule.source,data),expected=rule.value;if(actual==null)return false;switch(rule.operator){case'lt':return Number(actual)<Number(expected);case'lte':return Number(actual)<=Number(expected);case'eq':return String(actual)===String(expected);case'neq':return String(actual)!==String(expected);case'gte':return Number(actual)>=Number(expected);case'gt':return Number(actual)>Number(expected);default:return false;}}
export function activeRule(element,data){return (element.logic||[]).find(rule=>matches(rule,data))||null;}
export function resolvedStyle(element,data){const rule=activeRule(element,data),style=rule?.style||{};return {rule,fill:style.fill||element.fill,color:style.color||element.color,opacity:style.opacity??element.appearance?.opacity??1,text:style.text||'',animation:style.animation||element.animation?.kind||'none'};}
